  (function mergeGlossaryIntoDictionary() {
    var pack = window.CCE_MASTER_DYNASTIC_CHRONOLOGY_AND_GLOSSARY;
    var terms = (pack && Array.isArray(pack.glossary)) ? pack.glossary : [];
    if (!terms.length || !Array.isArray(window.CCE_DICTIONARY)) return;
    var seen = {};
    for (var i = 0; i < window.CCE_DICTIONARY.length; i++) {
      if (window.CCE_DICTIONARY[i] && window.CCE_DICTIONARY[i].hanzi) seen[window.CCE_DICTIONARY[i].hanzi] = true;
    }
    var added = 0;
    for (var j = 0; j < terms.length; j++) {
      var t = terms[j];
      if (!t || !t.hanzi || seen[t.hanzi]) continue;
      seen[t.hanzi] = true;
      window.CCE_DICTIONARY.push({
        id: 'v104-term-' + (j + 1),
        hanzi: t.hanzi,
        traditional: t.hanzi,
        pinyin: t.pinyin || '',
        hanViet: t.hanViet || '',
        level: 'Chuyên ngành',
        pos: 'Thuật ngữ',
        vietnamese: t.definitionVi || '',
        english: t.definitionEn || t.hanViet || t.hanzi,
        context: t.monographId ? ('Chuyên luận: ' + t.monographId) : 'V10.4 Scholarly Glossary'
      });
      added++;
    }
    if (added > 0 && window.CCE_SEARCH && typeof window.CCE_SEARCH.markDirty === 'function') window.CCE_SEARCH.markDirty();
  })();
